tenants = ENV_JAVA['bach.policies.hbase.tenants'].split(',').map { |tenant| tenant.split(':') }
tenants.each do |namespace, role_account|
  # FIXME list_namespace doesn't return any data and dumps everything to the
  # $stdout. It has been tested in tests that exceptions generated by
  # created_namespace gets ignored and hbase shell will iterate through this
  # list.
  create_namespace namespace
  grant role_account, 'RWCAX', "@#{namespace}"
end
